        'categories'=>['بنود وتصنيفات المصروفات','Expense categories & classifications'],'reports'=>['التقارير المالية وتحليل النفقات','Financial reports & expense analysis'],
        'employees'=>['إدارة الموظفين والكوادر','Employee & staff management'],'payroll'=>['مسيرات وصرف الرواتب','Payroll runs'],
        'settings'=>['إعدادات الشركة والمقر','Company & office settings'],
        'category'=>['بند مصروف','Expense category'],'employee'=>['ملف موظف','Employee profile'],'opening'=>['قيد افتتاحي · دون حركة نقدية جديدة','Opening GL · no new cash movement'],'deposit'=>['طلب إيداع','Deposit request'],
        'receipt'=>['سند قبض','Cash receipt voucher'],'expense'=>['طلب مصروف','Expense request'],'advance'=>['طلب عهدة','Advance request'],'advance_return'=>['طلب مرتجع عهدة','Advance return request'],'advance_settlement'=>['تسوية عهدة بمصروف','Advance expense settlement']];
    private function t(string $ar,string $en): string{return $this->ar?$ar:$en;}
    private static function e($v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private function label(string $key): string{return self::LABELS[$key][$this->ar?0:1]??$key;}
    private function url(array $extra=[]): string{$base=['lang'=>$this->lang,'office'=>$this->s['office'],'view'=>$this->s['view']];if($this->s['view']==='advances'||($this->s['view']==='treasury'&&$this->s['kind']==='opening'))$base['kind']=$this->s['kind'];if($this->s['view']==='reports'&&$this->s['report'])$base+=['from'=>$this->s['report']['from'],'to'=>$this->s['report']['to'],'kind'=>$this->s['report']['filter'],'status'=>$this->s['report']['status'],'currency'=>$this->s['report_currency'],'month'=>$this->s['month']];return 'workspace.php?'.http_build_query(array_replace($base,$extra));}
    private function status(string $status): string {return ['draft'=>$this->t('مسودة · غير مسجلة ماليًا','Draft · not posted'),'active'=>$this->t('نشط','Active'),'archived'=>$this->t('مؤرشف','Archived'),'submitted'=>$this->t('بانتظار الاعتماد','Submitted'),'approved'=>$this->t('معتمد · لم يُدفع بعد','Approved · unpaid'),'posted'=>$this->t('منفذ ومرحل ماليًا','Paid / received & posted'),'rejected'=>$this->t('مُعاد للتصحيح','Returned for correction'),'reversed'=>$this->t('معكوس ماليًا','Reversed')][$status]??$status;}
    private function name(int $id): string {foreach($this->s['staff']as$p)if($p['id']===$id)return trim($p['name'])!==''?$p['name']:$p['login'];return '#'.$id;}
    private function money(string $value,string $currency): string{return '<bdi>'.self::e($value.' '.$currency).'</bdi>';}
    private function hidden(string $name,$value): string{return '<input type="hidden" name="'.self::e($name).'" value="'.self::e($value).'">';}
    private function tokens(string $action,string $kind,string $id='',int $revision=0): string
    {
        $h='';foreach(['token'=>$this->csrf,'action'=>$action,'view'=>$this->s['view'],'kind'=>$kind,'office'=>$this->s['office'],'lang'=>$this->lang,'id'=>$id,'revision'=>$revision]as$k=>$v)$h.=$this->hidden($k,$v);return $h;
    }
    public function render(array $state,string $csrf): string
    {
        $this->s=$state;$this->lang=$state['language'];$this->ar=$this->lang==='ar';$this->csrf=$csrf;
        $nav=OfficeExpenseStaffPage::navigation($this->lang,$state['view'],!empty($state['manage_staff']),$state['office'],true,$state['navigation_views']??null);
        $bufferLevel=ob_get_level();ob_start();try{ ?>
<div class="office-expenses-app workspace-app<?= $state['view']==='receipts'?' receipts-app':($state['view']==='reports'?' reports-app':'') ?><?= $state['print']&&$state['kind']==='receipt'?' receipt-print-mode':'' ?>" lang="<?= $this->lang ?>" dir="<?= $this->ar?'rtl':'ltr' ?>"><div class="app-layout"><aside class="app-sidebar" aria-label="<?= $this->t('القائمة الرئيسية','Main menu') ?>"><a class="brand" href="<?= self::e(OfficeExpenseStaffPage::homeUrl($this->lang,$state['office'],$state['navigation_views']??null)) ?>"><span class="brand-icon"><i class="fa-solid fa-coins" aria-hidden="true"></i></span><span><b><?= $this->t('فينانس ساس','Finens SaaS') ?></b><small><?= $this->t('لوحة تحكم الشركات','Company dashboard') ?></small></span></a><nav><?= $nav ?></nav></aside><div class="app-content"><header class="app-navbar"><div class="company-context"><span class="company-icon"><i class="fa-solid fa-building" aria-hidden="true"></i></span><div><strong>China Planet</strong><small><?= $this->t($state['office']==='china'?'فرع الصين':'فرع مصر',$state['office']==='china'?'China office':'Egypt office') ?></small></div></div><a class="language-link" href="<?= self::e($this->url(['lang'=>$this->ar?'en':'ar','edit'=>$state['selected']['id']??null])) ?>"><?= $this->ar?'English':'العربية' ?></a></header><details class="workspace-mobile-menu"><summary><i class="fa-solid fa-bars" aria-hidden="true"></i> <?= $this->t('القائمة الرئيسية','Main menu') ?></summary><nav><?= $nav ?></nav></details><main>
<div class="page-heading"><div><h1><?= self::e($this->label($state['view'])) ?></h1><p><?= $state['view']==='receipts'?$this->t('تسجيل بيانات العميل والمستلم، وطباعة 3 وصولات في صفحة A4 واحدة','Record payer and recipient details, and print 3 receipt copies on one A4 sheet'):$this->t('متابعة وإدارة بيانات الفرع وصلاحياته','Manage the records and permissions of this branch') ?></p></div><div class="workspace-heading-actions"><?php if($state['view']!=='overview'){ ?><a class="button button-muted workspace-back" data-workspace-back href="<?= self::e(OfficeExpenseStaffPage::homeUrl($this->lang,$state['office'],$state['navigation_views']??null)) ?>"><i class="fa-solid fa-arrow-<?= $this->ar?'right':'left' ?>" aria-hidden="true"></i><?= $this->t('رجوع','Back') ?></a><?php }if($state['view']==='reports'){ ?><button class="button button-dark" type="button" data-workspace-print><i class="fa-solid fa-print" aria-hidden="true"></i><?= $this->t('طباعة التقرير المالي','Print financial report') ?></button><?php } ?><?php if(!in_array($state['view'],['reports','overview'],true)&&($state['permissions']['create']??false)){ ?><a class="button <?= $state['view']==='receipts'?'receipt-green-button':'button-brand' ?>"<?= $state['view']==='receipts'?' data-receipt-open':($state['view']!=='settings'?' data-workspace-open':'') ?> href="<?= self::e($this->url(['edit'=>null])) ?>#workspace-form"><i class="fa-solid fa-plus" aria-hidden="true"></i> <?= $this->t('إضافة جديد','Add new') ?></a><?php } ?></div></div>
<form method="get" action="workspace.php" class="workspace-branch"><input type="hidden" name="lang" value="<?= $this->lang ?>"><input type="hidden" name="view" value="<?= self::e($state['view']) ?>"><label for="workspace-office"><?= $this->t('الفرع','Branch') ?></label><select id="workspace-office" name="office"><?php foreach($state['offices']as$office=>$currencies){ ?><option value="<?= $office ?>"<?= $state['office']===$office?' selected':'' ?>><?= $this->t($office==='china'?'الصين':'مصر',ucfirst($office)) ?></option><?php } ?></select><button class="button button-muted" type="submit"><?= $this->t('عرض الفرع','View branch') ?></button></form>
<?php if($state['error']){ ?><div class="flash error" role="alert"><?= $this->t('لم يُؤكد حفظ الطلب. تحقق من الصلاحية والحقول والتاريخ، ثم أعد فتح السجل قبل المحاولة.','The request was not confirmed. Check access, fields and dates, then reopen the record before retrying.') ?></div><?php if($state['form']){ ?><details class="workspace-card"><summary><?= $this->t('البيانات المُرسلة لإعادة المحاولة','Submitted values for retry') ?></summary><dl><?php foreach($state['form']as$k=>$v)if(is_string($v)){ ?><dt><?= self::e($k) ?></dt><dd><?= self::e($v) ?></dd><?php } ?></dl></details><?php } }else{
if($state['print']){if($state['kind']==='receipt')$this->receiptPrint($state['selected']);else $this->printDocument($state['selected']);}
elseif($state['view']==='overview'){$this->overview();}
elseif($state['view']==='reports'){$this->reports();}
elseif($state['view']==='receipts'){$this->receipts();}
else{
if($state['view']==='treasury')$this->treasury();
if(in_array($state['view'],['employees','payroll'],true))$this->sectionSummary();
if($state['view']==='employees')$this->employeeDirectory();
if($state['view']==='settings'){$this->letterhead($state['selected']['content']??['name'=>'China Planet','phone'=>'']);$this->cashAccounts();}
if($state['view']==='categories')$this->categories();else $this->register();
if($state['view']==='advances'){ ?><div class="workspace-tabs"><a href="<?= self::e($this->url(['kind'=>'advance','edit'=>null])) ?>#workspace-form"><?= $this->t('عهدة جديدة','New advance') ?></a><a href="<?= self::e($this->url(['kind'=>'advance_return','edit'=>null])) ?>#workspace-form"><?= $this->t('مرتجع عهدة','Return an advance') ?></a><a href="<?= self::e($this->url(['kind'=>'advance_settlement','edit'=>null])) ?>#workspace-form"><?= $this->t('تسوية بمصروف','Expense settlement') ?></a></div><?php }
$this->editor();
if($state['selected']&&!($state['permissions']['update']??false))$this->details($state['selected']);
if($state['history']){ ?><details class="workspace-card"><summary><?= $this->t('سجل التعديلات','Revision history') ?></summary><ol><?php foreach($state['history']as$h){ ?><li><?= self::e('#'.$h['revision'].' · '.$h['action'].' · #'.$h['fk_actor'].' · '.$h['date_creation']) ?></li><?php } ?></ol></details><?php }
}
} ?>
<?php if(!$state['error'])echo (new OfficeExpenseFinancialPage())->render($state,$csrf); ?>
</main></div></div></div>
<?php return (string)ob_get_clean();}catch(Throwable $e){while(ob_get_level()>$bufferLevel)ob_end_clean();throw $e;}
    }
    private function overview(): void
    {
        $r=$this->s['report'];$cash=$r['cash'];$currency=OfficeExpenseStaffAccess::OFFICES[$this->s['office']][0];
        ?><section class="overview-welcome workspace-card"><div><h2><?= $this->t('مرحبًا بك، ','Welcome, ').self::e($this->s['actor_name']) ?></h2><p><?= $this->t('متابعة الخزنة والمصروفات اليومية للفرع','Follow branch cash and daily expense requests') ?></p></div><div class="workspace-heading-actions"><?php foreach(['receipt'=>['receipts','file-invoice-dollar','وصل استلام نقدية','Cash receipt voucher'],'deposit'=>['treasury','circle-plus','طلب إيداع في الخزنة','Deposit request'],'expense'=>['expenses','circle-minus','تسجيل مصروف','Record expense']]as$kind=>[$view,$icon,$ar,$en])if($this->s['overview_actions'][$kind]??false){ ?><a class="button <?= $kind==='expense'?'button-rose':($kind==='deposit'?'receipt-green-button':'button-brand') ?>" href="<?= self::e('workspace.php?'.http_build_query(['lang'=>$this->lang,'office'=>$this->s['office'],'view'=>$view])) ?>#workspace-form"><i class="fa-solid fa-<?= $icon ?>" aria-hidden="true"></i><?= $this->t($ar,$en) ?></a><?php } ?></div></section><?php
        if($cash&&!$cash['restricted'])$this->cashCards($cash['accounts'],true);
        else{ ?><section class="section-summary"><article><div><p><?= $this->t('طلبات المصروفات المتاحة لك','Your permitted expense requests') ?></p><?php foreach($r['totals']as$c=>$totals){ ?><strong><?= $this->money($totals['expense']??'0.00',$c) ?></strong><?php } ?><small><?= $this->t('مسودات · غير مدفوعة','Drafts · unpaid') ?></small></div><span class="summary-icon summary-rose"><i class="fa-solid fa-receipt" aria-hidden="true"></i></span></article><article><div><p><?= $this->t('عدد الطلبات','Request count') ?></p><strong><?= count($r['rows']) ?></strong></div><span class="summary-icon"><i class="fa-solid fa-list" aria-hidden="true"></i></span></article></section><?php }
        ?><div class="overview-details"><section class="register-panel"><div class="workspace-register-title"><div><h2><?= $this->t('آخر الطلبات والمصروفات','Recent requests & expenses') ?></h2><p><?= $this->t('مسودات تشغيلية · لا تمثل دفعات فعلية','Operational drafts · not actual payments') ?></p></div><a href="<?= self::e($this->url(['view'=>'expenses'])) ?>"><?= $this->t('عرض كامل السجل ←','View register →') ?></a></div><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $this->t('آخر الطلبات','Recent requests') ?>"><table><thead><tr><th><?= $this->t('النوع','Type') ?></th><th><?= $this->t('البند / السبب','Description') ?></th><th><?= $this->t('المبلغ','Amount') ?></th><th><?= $this->t('التاريخ','Date') ?></th><th><?= $this->t('الحالة','Status') ?></th></tr></thead><tbody><?php foreach(array_slice($r['rows'],0,8)as$row){$v=$row['content']; ?><tr><td><?= self::e($this->label($row['kind'])) ?></td><td><strong><?= self::e($v['purpose']??$v['notes']??'') ?></strong></td><td class="workspace-amount"><?= $this->money($v[$row['kind']==='payroll'?'net':'amount'],$v['currency']) ?></td><td><bdi><?= self::e($v['date']) ?></bdi></td><td><?= self::e($this->status($row['status'])) ?></td></tr><?php }if(!$r['rows']){ ?><tr><td colspan="5" class="empty"><?= $this->t('لا توجد طلبات خلال الشهر.','No requests this month.') ?></td></tr><?php } ?></tbody></table></div></section><section class="workspace-card overview-spending"><h2><?= $this->t('أعلى بنود طلبات الصرف هذا الشهر','Top expense request categories this month') ?></h2><p><?= $this->t('توزيع الطلبات · كل عملة مستقلة','Request distribution · currencies stay separate') ?></p><?php $shown=false;foreach($r['charts']??[]as$c=>$series)if($series['categories']){$shown=true; ?><h3><?= self::e($c) ?></h3><?= $this->categoryChart($series['categories'],$c) ?><?php }if(!$shown){ ?><p class="empty"><?= $this->t('لا توجد بيانات للعرض.','No data to display.') ?></p><?php } ?><a class="button button-muted" href="<?= self::e($this->url(['view'=>'reports'])) ?>"><?= $this->t('عرض التقارير والرسوم البيانية الكاملة','View full reports & charts') ?></a></section></div><?php
    }
    private function cashCards(array $accounts,bool $withNet=false): void
    {
        foreach($accounts as$account){ ?><section class="cash-summary-row<?= $withNet?' cash-summary-with-net':'' ?>"><div class="workspace-vault"><span><i class="fa-solid fa-vault" aria-hidden="true"></i> <?= $this->t('الخزنة الرئيسية','Main cash account') ?> · <?= self::e($account['currency']) ?></span><p><?= $this->t('الرصيد الفعلي المتوفر حاليًا','Available as of Dolibarr date') ?></p><strong><?= $this->money($account['available_balance'],$account['currency']) ?></strong><small><bdi><?= self::e($account['reference'].' · '.$account['as_of']) ?></bdi><br><?= $this->t('الرصيد المسجل','Recorded balance') ?>: <?= $this->money($account['balance'],$account['currency']) ?></small></div><?php foreach([['period_in','إيداعات الفترة','Period cash in','arrow-down-long','emerald'],['period_out','مسحوبات الفترة','Period cash out','arrow-up-long','rose']]as[$key,$ar,$en,$icon,$color]){ ?><article class="cash-month-card"><div><span><?= $this->t($ar,$en) ?></span><i class="summary-icon summary-<?= $color ?> fa-solid fa-<?= $icon ?>" aria-hidden="true"></i></div><div><strong class="cash-<?= $color ?>"><?= isset($account[$key])?$this->money($account[$key],$account['currency']):'—' ?></strong><p><?= $this->t('حركة Dolibarr فعلية · دون الأرصدة الافتتاحية','Posted Dolibarr movement · excluding openings') ?></p></div></article><?php }if($withNet){ ?><article class="cash-month-card"><div><span><?= $this->t('صافي حركة الفترة','Net period cash movement') ?></span><i class="summary-icon summary-amber fa-solid fa-scale-balanced" aria-hidden="true"></i></div><div><strong class="cash-amber"><?= $this->money(bcsub($account['period_in'],$account['period_out'],2),$account['currency']) ?></strong><p><?= $this->t('داخل ناقص خارج · دون الأرصدة الافتتاحية','Cash in less cash out · excluding openings') ?></p></div></article><?php } ?></section><?php }
    }
    private function sectionSummary(): void
    {
        $employee=$this->s['view']==='employees';$sums=[];foreach($this->s['rows']as$row)if($row['status']!=='archived'){$v=$row['content'];$sums[$v['currency']]=bcadd($sums[$v['currency']]??'0.00',$v[$employee?'salary':'net'],2);}
        ?><section class="section-summary"><?php if(!$employee){ ?><article><div><label for="payroll-month"><?= $this->t('الشهر الحالي المحدد','Selected month') ?></label><form method="get" action="workspace.php"><?php foreach(['lang'=>$this->lang,'office'=>$this->s['office'],'view'=>'payroll']as$key=>$value)echo $this->hidden($key,$value); ?><input id="payroll-month" name="month" type="month" value="<?= self::e($this->s['month']) ?>" required><button class="button button-muted"><?= $this->t('عرض','View') ?></button></form></div></article><?php }else{ ?><article><div><p><?= $this->t('إجمالي الموظفين المعيّنين','Assigned staff') ?></p><strong><?= count($this->s['staff']) ?></strong></div><span class="summary-icon summary-purple"><i class="fa-solid fa-users" aria-hidden="true"></i></span></article><?php } ?><article><div><p><?= $this->t($employee?'إجمالي الرواتب المسجّلة':'إجمالي صافي مسيرات الرواتب',$employee?'Recorded base salaries':'Net payroll requests') ?></p><?php foreach($sums as$c=>$sum){ ?><strong class="cash-emerald"><?= $this->money($sum,$c) ?></strong><?php }if(!$sums){ ?><strong>—</strong><?php } ?><small><?= $this->t('كل عملة مستقلة · ليست دفعات فعلية','Separate currencies · not actual payments') ?></small></div><span class="summary-icon summary-teal"><i class="fa-solid fa-wallet" aria-hidden="true"></i></span></article><article><div><p><?= $this->t($employee?'حالة إدارة الموظفين':'عدد المسيرات',$employee?'Staff management':'Payroll request count') ?></p><strong class="cash-emerald"><?= $employee?$this->t('متاحة للفرع','Available to branch'):count($this->s['rows']) ?></strong></div><span class="summary-icon summary-emerald"><i class="fa-solid fa-circle-check" aria-hidden="true"></i></span></article></section><?php
    }
    private function editableRow(array $row,string $action): bool {if(!($this->s['permissions'][$action]??false))return false;if($row['kind']==='opening'&&empty($this->s['finance']['administrator']))return false;if(($this->s['record_scope']??'branch')!=='own')return true;$actor=$this->s['actor_id']??0;return in_array($row['kind'],['employee','payroll'],true)?$row['subject']===$actor:$row['owner']===$actor;}
    private function editor(): void
    {
        if($this->s['kind']==='settings'){$this->form();return;}
        $row=$this->s['selected'];if($this->s['kind']==='opening')return;if(($row&&(!($this->s['permissions']['update']??false)||!in_array($row['status'],['draft','rejected','active'],true)))||(!$row&&!($this->s['permissions']['create']??false)))return;
        ?><dialog class="workspace-modal" id="workspace-editor" aria-labelledby="workspace-editor-title"<?= $row?' data-workspace-auto-open':'' ?>><header><h2 id="workspace-editor-title"><?= self::e(($row?$this->t('تعديل · ','Edit · '):$this->t('إضافة · ','Add · ')).$this->label($this->s['kind'])) ?></h2><button type="button" class="button button-muted" data-workspace-close aria-label="<?= $this->t('إغلاق','Close') ?>"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button></header><?php $this->form(); ?><button type="button" class="button button-muted workspace-cancel" data-workspace-close><?= $this->t('إلغاء','Cancel') ?></button></dialog><?php
    }
    private function cashAccounts(): void
    { ?><section class="workspace-card"><h2><?= $this->t('خزائن الفرع في Dolibarr','Native branch cash accounts') ?></h2><div class="workspace-people"><?php foreach($this->s['accounts']as$account){ ?><span><i class="fa-solid fa-vault" aria-hidden="true"></i> <bdi><?= self::e($account['reference'].' · '.$account['currency']) ?></bdi></span><?php } ?></div><p><?= $this->t('خزنة مستقلة لكل عملة. الأرصدة والحركات من Dolibarr؛ اختيار تلقائي لا يلغي ربط الخزائن.','Each currency has its own cash account. Dolibarr owns balances and entries; automatic selection keeps these mappings active.') ?></p></section><?php }
    private function treasury(): void
    {
        $cash=$this->s['cash'];if(!$cash)return;
        if($cash['restricted']){ ?><p class="workspace-card"><?= $this->t('صلاحيتك تتيح سجلاتك فقط؛ رصيد الفرع وكشف حركته متاحان للمخوّلين بقراءة خزنة الفرع.','Your access covers your own records. Branch balances and statements require branch treasury read access.') ?></p><?php return;}
        ?><form method="get" action="workspace.php" class="workspace-card treasury-date-filter"><?php foreach(['view'=>'treasury','lang'=>$this->lang,'office'=>$this->s['office']]as$key=>$value)echo $this->hidden($key,$value); ?><div><label for="treasury-from"><?= $this->t('من تاريخ','From date') ?></label><input id="treasury-from" name="from" type="date" value="<?= self::e($cash['from']) ?>" required></div><div><label for="treasury-to"><?= $this->t('إلى تاريخ','To date') ?></label><input id="treasury-to" name="to" type="date" value="<?= self::e($cash['to']) ?>" required></div><button class="button button-brand" type="submit"><?= $this->t('تصفية الحركات','Filter movements') ?></button></form><?php
        $this->cashCards($cash['accounts']);
        ?>
        <?php foreach($cash['accounts']as$account){ ?><section class="register-panel"><div class="workspace-register-title"><h2><?= $this->t('كشف حركة الخزنة','Native cash statement') ?> · <?= self::e($account['currency']) ?></h2><span><?= $this->t('أحدث 100 حركة كحد أقصى','Latest 100 entries maximum') ?></span></div><div class="table-scroll" tabindex="0" role="region" aria-label="<?= self::e($this->t('كشف حركة ','Cash statement ').$account['currency']) ?>"><table><thead><tr><th><?= $this->t('المرجع','Reference') ?></th><th><?= $this->t('التاريخ','Date') ?></th><th><?= $this->t('البيان','Description') ?></th><th><?= $this->t('المبلغ','Amount') ?></th></tr></thead><tbody><?php foreach($account['entries']as$entry){ ?><tr><td><bdi>#<?= $entry['id'] ?></bdi></td><td><bdi><?= self::e($entry['date']) ?></bdi></td><td><?= self::e($entry['opening']?$this->t('رصيد افتتاحي · ليس إيرادًا','Opening balance · not revenue'):$entry['label']) ?><?php if($entry['future']){ ?><small class="workspace-row-note"><?= $this->t('مؤرخة لاحقًا · غير متاحة الآن','Future dated · not available yet') ?></small><?php } ?></td><td class="workspace-amount"><?= $this->money($entry['amount'],$account['currency']) ?></td></tr><?php }if(!$account['entries']){ ?><tr><td colspan="4" class="empty"><?= $this->t('لا توجد حركات مسجلة.','No posted entries.') ?></td></tr><?php } ?></tbody></table></div><?php if($account['has_more']){ ?><p class="workspace-help"><?= $this->t('توجد حركات أقدم في سجل Dolibarr. الرصيد المعروض يشمل جميع الحركات.','Older entries exist in Dolibarr. The displayed balance includes all entries.') ?></p><?php } ?></section><?php }
