        <div class="report-options"><div><label for="report-currency"><?= $this->t('العملة · دون تحويل أو تجميع','Currency · no conversion or pooling') ?></label><select id="report-currency" name="currency"><?php foreach(OfficeExpenseStaffAccess::OFFICES[$this->s['office']]as$c){ ?><option<?= $currency===$c?' selected':'' ?>><?= self::e($c) ?></option><?php } ?></select></div><div><label for="report-kind"><?= $this->t('نوع الطلب','Request type') ?></label><select id="report-kind" name="kind"><?php foreach(['all','expense','deposit','receipt','advance','advance_return','payroll']as$k){ ?><option value="<?= $k ?>"<?= $k===$r['filter']?' selected':'' ?>><?= self::e($k==='all'?$this->t('الكل','All'):$this->label($k)) ?></option><?php } ?></select></div><div><label for="report-status"><?= $this->t('الحالة','Status') ?></label><select id="report-status" name="status"><?php foreach(['all','draft','submitted','approved','posted','rejected','reversed','archived']as$k){ ?><option value="<?= $k ?>"<?= $k===$r['status']?' selected':'' ?>><?= self::e($k==='all'?$this->t('الكل','All'):$this->status($k)) ?></option><?php } ?></select></div><div class="report-export-actions"><button class="button button-muted" name="export" value="csv"><?= $this->t('تصدير الطلبات CSV','Requests CSV') ?></button><?php if($r['cash']){ ?><button class="button button-muted" name="export" value="cash_csv"><?= $this->t('تصدير الخزنة CSV','Cash CSV') ?></button><?php } ?></div></div></form></section>
