        <div class="report-original-metrics"><?php $net=bcsub(bcsub($totals['deposit']??'0.00',$totals['expense']??'0.00',2),$totals['payroll']??'0.00',2);foreach([['deposit','طلبات الإيداع','Deposit requests','داخل الخزنة بعد الاعتماد','Cash in after approval'],['expense','طلبات المصروفات','Expense requests','نفقات تشغيلية وبنود','Operating expense requests'],['payroll','مسيرات الرواتب','Payroll requests','صافي الرواتب · غير مدفوع','Net payroll · unpaid'],['net','صافي الطلبات','Net requests','لا يمثل رصيد الخزنة','Not a cash balance']]as$i=>[$key,$ar,$en,$arHelp,$enHelp]){ ?><article class="report-metric report-metric-<?= $key ?><?= $key==='net'&&bccomp($net,'0',2)<0?' report-negative':'' ?>"><span><?= $this->t($ar,$en) ?></span><strong><?= $this->money($key==='net'?$net:($totals[$key]??'0.00'),$currency) ?></strong><small><?= $this->t($arHelp,$enHelp) ?></small></article><?php } ?></div></section>
        <div class="report-charts"><section class="report-chart-panel"><header><div><h2><?= $this->t('مقارنة الشهور (آخر 6 أشهر)','Monthly comparison (last 6 months)') ?></h2><p><?= $this->t('طلبات الإيداع والمصروفات · غير مرحلة','Deposit and expense requests · not posted') ?></p></div><span class="report-chart-icon"><i class="fa-solid fa-chart-column" aria-hidden="true"></i></span></header><?= $this->monthlyChart($series['months'],$currency) ?></section><section class="report-chart-panel"><header><div><h2><?= $this->t('توزيع المصروفات حسب البند','Expense distribution by category') ?></h2><p><?= $this->t('الطلبات غير المؤرشفة خلال الفترة المحددة','Unarchived requests in the selected period') ?></p></div><span class="report-chart-icon report-chart-icon-rose"><i class="fa-solid fa-chart-pie" aria-hidden="true"></i></span></header><?= $this->categoryChart($series['categories'],$currency) ?></section></div>
        <section class="register-panel report-monthly-table"><div class="workspace-register-title"><h2><?= $this->t('جدول المقارنة الشهرية للأشهر الستة الأخيرة','Monthly comparison for the last six months') ?></h2><span><?= self::e($currency) ?></span></div><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $this->t('المقارنة الشهرية','Monthly comparison') ?>"><table><thead><tr><?php foreach([['الشهر','Month'],['طلبات الإيداع','Deposit requests'],['طلبات المصروفات','Expense requests'],['صافي الرواتب','Net payroll'],['صافي الطلبات','Net requests']]as[$ar,$en]){ ?><th><?= $this->t($ar,$en) ?></th><?php } ?></tr></thead><tbody><?php foreach($series['months']as$month){ ?><tr><td><bdi><?= self::e($month['month']) ?></bdi></td><?php foreach(['deposit','expense','payroll','net']as$key){ ?><td class="report-number report-number-<?= $key ?>"><?= $this->money($month[$key],$currency) ?></td><?php } ?></tr><?php } ?></tbody></table></div></section>
