    private function monthlyChart(array $months,string $currency): string
    {
        $max='0.00';foreach($months as$m)foreach(['deposit','expense']as$key)if(bccomp($m[$key],$max,2)>0)$max=$m[$key];
        $id='monthly-chart-'.strtolower($currency);$h='<div class="report-chart" data-report-chart><svg class="monthly-chart" viewBox="0 0 560 256" role="img" aria-labelledby="'.$id.'"><title id="'.$id.'">'.$this->t('مقارنة الطلبات الشهرية','Monthly request comparison').' · '.self::e($currency).'</title>';
        for($i=0;$i<5;$i++){$y=202-$i*42;$tick=bcdiv(bcmul($max,(string)$i,2),'4',2);$h.='<line x1="54" x2="548" y1="'.$y.'" y2="'.$y.'" class="chart-grid"/><text x="46" y="'.($y+4).'" text-anchor="end" class="chart-tick">'.self::e($tick).'</text>';}
        foreach($months as$i=>$month){$x=72+$i*80;foreach(['deposit','expense']as$j=>$key){$height=bccomp($max,'0',2)>0?(float)bcdiv(bcmul($month[$key],'168',8),$max,4):0;$height=max(0,min(168,$height));$label=$month['month'].' · '.$this->t($key==='deposit'?'طلبات إيداع':'طلبات مصروفات',$key==='deposit'?'Deposit requests':'Expense requests').' · '.$month[$key].' '.$currency;$h.='<rect x="'.($x+$j*25).'" y="'.(202-$height).'" width="23" height="'.$height.'" rx="6" class="chart-bar chart-bar-'.$key.'" tabindex="0" data-chart-label="'.self::e($label).'"><title>'.self::e($label).'</title></rect>';}$h.='<text x="'.($x+24).'" y="225" text-anchor="middle" class="chart-tick">'.self::e($month['month']).'</text>';}
        $h.='</svg><p class="chart-tooltip" role="status" hidden></p></div><div class="chart-legend"><span><i class="chart-swatch chart-swatch-deposit"></i>'.$this->t('طلبات الإيداع','Deposit requests').'</span><span><i class="chart-swatch chart-swatch-expense"></i>'.$this->t('طلبات المصروفات','Expense requests').'</span></div>';
        if(bccomp($max,'0',2)===0)$h.='<p class="chart-empty-note">'.$this->t('لا توجد طلبات خلال هذه الشهور.','No requests in these months.').'</p>';
        return $h;
    }
    private function categoryChart(array $categories,string $currency): string
    {
        $total='0.00';foreach($categories as$c)$total=bcadd($total,$c['amount'],2);
        if(bccomp($total,'0',2)<=0)return '<div class="chart-empty">'.$this->t('لا توجد مصروفات مسجلة لهذه الفترة لعرض الرسم البياني.','No expenses in this period to chart.').'</div>';
        $id='category-chart-'.strtolower($currency);$h='<div class="report-chart doughnut-chart" data-report-chart><svg viewBox="0 0 240 240" role="img" aria-labelledby="'.$id.'"><title id="'.$id.'">'.$this->t('توزيع طلبات المصروفات','Expense request distribution').' · '.self::e($currency).'</title><circle cx="120" cy="120" r="80" class="chart-ring-base"/>';$offset=0.0;$legend='';
        foreach($categories as$i=>$c){$ratio=(float)bcdiv(bcmul($c['amount'],'100',8),$total,5);$name=$c['name']??$this->t('غير مصنف','Uncategorized');$label=$name.' · '.$c['amount'].' '.$currency.' · '.bcdiv(bcmul($c['amount'],'100',4),$total,1).'%';$color=$i%7;
            $h.='<circle cx="120" cy="120" r="80" pathLength="100" stroke-dasharray="'.$ratio.' '.(100-$ratio).'" stroke-dashoffset="'.(-$offset).'" transform="rotate(-90 120 120)" class="chart-segment chart-palette-'.$color.'" tabindex="0" data-chart-label="'.self::e($label).'"><title>'.self::e($label).'</title></circle>';$offset+=$ratio;$legend.='<li><i class="chart-swatch chart-palette-'.$color.'"></i><span>'.self::e($name).'</span><bdi>'.self::e($c['amount'].' '.$currency).'</bdi></li>';}
        return $h.'</svg><p class="chart-tooltip" role="status" hidden></p></div><ul class="category-legend">'.$legend.'</ul>';
    }
    private function nativeCashReport(array $r): void
    { ?><?php if($r['cash']){ ?><section class="register-panel"><div class="workspace-register-title"><h2><?= $this->t('حركات الخزنة المسجّلة في Dolibarr خلال الفترة','Recorded Dolibarr cash movements during the period') ?></h2></div><p class="workspace-help"><?= $this->t('كل عملة مستقلة. الرصيد الافتتاحي ليس إيرادًا؛ والحركة الداخلة أو الخارجة لا تعني تلقائيًا إيرادًا أو مصروفًا.','Currencies remain separate. Initial balances are not revenue; cash in or out does not automatically mean revenue or expense.') ?></p><div class="table-scroll" tabindex="0"><table><thead><tr><th><?= $this->t('العملة','Currency') ?></th><th><?= $this->t('رصيد أول الفترة','Balance before period') ?></th><th><?= $this->t('افتتاحيات خلال الفترة','Initial balances in period') ?></th><th><?= $this->t('داخل الخزنة','Cash in') ?></th><th><?= $this->t('خارج الخزنة','Cash out') ?></th><th><?= $this->t('رصيد مسجّل آخر الفترة','Recorded closing') ?></th></tr></thead><tbody><?php foreach($r['cash']['accounts']as$account){ ?><tr><td><?= self::e($account['currency']) ?></td><?php foreach(['period_opening','period_initial','period_in','period_out','period_closing']as$field){ ?><td class="workspace-amount"><?= $this->money($account[$field],$account['currency']) ?></td><?php } ?></tr><?php } ?></tbody></table></div></section><?php } ?>
<?php
    }
