    private function receiptTransitions(array $row): string
    {
        if(!($this->s['permissions']['delete']??false)||!in_array($row['status'],['draft','rejected','archived'],true))return '';$action=$row['status']==='archived'?'restore':'archive';
        return '<details class="receipt-transition"><summary>'.$this->t($action==='archive'?'أرشفة':'استرجاع',$action==='archive'?'Archive':'Restore').'</summary><form method="post" action="workspace.php">'.$this->tokens($action,'receipt',$row['id'],$row['revision']).'<p>'.$this->t('تُحفظ البيانات وسجل التعديلات.','Records and history are retained.').'</p><button class="button button-rose">'.$this->t('تأكيد','Confirm').'</button></form></details>';
    }
    private static function receiptWords(string $amount,string $currency,bool $arabic): string
    {
        $amount=(new OfficeExpenseMoney())->amount($amount,$currency);[$whole,$fraction]=explode('.',$amount);
        $arUnits=['صفر','واحد','اثنان','ثلاثة','أربعة','خمسة','ستة','سبعة','ثمانية','تسعة','عشرة','أحد عشر','اثنا عشر','ثلاثة عشر','أربعة عشر','خمسة عشر','ستة عشر','سبعة عشر','ثمانية عشر','تسعة عشر'];
        $arTens=[2=>'عشرون',3=>'ثلاثون',4=>'أربعون',5=>'خمسون',6=>'ستون',7=>'سبعون',8=>'ثمانون',9=>'تسعون'];$arHundreds=[1=>'مائة',2=>'مائتان',3=>'ثلاثمائة',4=>'أربعمائة',5=>'خمسمائة',6=>'ستمائة',7=>'سبعمائة',8=>'ثمانمائة',9=>'تسعمائة'];
        $enUnits=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];$enTens=[2=>'twenty',3=>'thirty',4=>'forty',5=>'fifty',6=>'sixty',7=>'seventy',8=>'eighty',9=>'ninety'];
        $group=function(int $n)use($arabic,$arUnits,$arTens,$arHundreds,$enUnits,$enTens): string{$parts=[];if($n>=100){$parts[]=$arabic?$arHundreds[intdiv($n,100)]:$enUnits[intdiv($n,100)].' hundred';$n%=100;}if($n){if($arabic)$parts[]=$n<20?$arUnits[$n]:($n%10?$arUnits[$n%10].' و':'').$arTens[intdiv($n,10)];else $parts[]=$n<20?$enUnits[$n]:$enTens[intdiv($n,10)].($n%10?'-'.$enUnits[$n%10]:'');}return implode($arabic?' و':' ',$parts);};
        $scales=$arabic?[['','',''],['ألف','ألفان','آلاف'],['مليون','مليونان','ملايين'],['مليار','ملياران','مليارات']]:['','thousand','million','billion'];$parts=[];
        for($i=0;$whole!=='0';$i++){$n=(int)bcmod($whole,'1000',0);$whole=bcdiv($whole,'1000',0);if(!$n)continue;if($i===0)$parts[]=$group($n);elseif($arabic)$parts[]=$n===1?$scales[$i][0]:($n===2?$scales[$i][1]:$group($n).' '.$scales[$i][$n>=3&&$n<=10?2:0]);else $parts[]=$group($n).' '.$scales[$i];}
        $words=$parts?implode($arabic?' و':' ',array_reverse($parts)):($arabic?'صفر':'zero');$units=$arabic?['EGP'=>'جنيه مصري','USD'=>'دولار أمريكي','CNY'=>'يوان صيني']:['EGP'=>'Egyptian pounds','USD'=>'US dollars','CNY'=>'Chinese yuan'];
        return ($arabic?'فقط ':'').$words.' '.$units[$currency].($fraction==='00'?'':($arabic?' و ':' and ').($arabic?"\u{2066}".$fraction.'/100'."\u{2069}":$fraction.'/100')).($arabic?' لا غير':' only');
    }
    private function receiptPrint(array $row): void
    {
        $brand=$this->receiptBrand();$v=$row['content'];$receiver=$this->s['receivers'][$row['owner']]??'#'.$row['owner'];$url=$this->s['receipt_link']??'';$qr='';
        if($url!==''&&defined('DOL_DOCUMENT_ROOT')){require_once DOL_DOCUMENT_ROOT.'/includes/tecnickcom/tcpdf/tcpdf_barcodes_2d.php';$barcode=new TCPDF2DBarcode($url,'QRCODE,L');$svg=$barcode->getBarcodeSVGcode(1,1);$qr=substr($svg,strpos($svg,'<svg'));}
        ?><div class="receipt-print-toolbar"><div><a class="button button-muted" href="<?= self::e($this->url(['edit'=>null,'print'=>null])) ?>"><i class="fa-solid fa-arrow-right" aria-hidden="true"></i> <?= $this->t('العودة لسجل الإيصالات','Back to receipt register') ?></a><h1><?= $this->t('معاينة طباعة ورقة A4 (3 وصولات استلام)','A4 print preview · 3 receipt copies') ?></h1><p><?= $this->t('رقم الإيصال الثابت:','Permanent receipt reference:') ?> <bdi><?= self::e($this->receiptReference($row)) ?></bdi></p></div><button class="button receipt-green-button" type="button" data-workspace-print><i class="fa-solid fa-print" aria-hidden="true"></i> <?= $this->t('طباعة الورقة الآن (A4)','Print A4 sheet') ?></button></div>
        <div class="receipt-paper-scroll"><div class="receipt-a4-page workspace-print-document" data-receipt-copies="3"><?php foreach([['أصل - نسخة العميل','Original · customer copy','customer'],['صورة - نسخة الحسابات والخزنة','Copy · accounts & cash','accounts'],['صورة - نسخة الأرشيف والسجلات','Copy · archive & records','archive']]as$i=>[$ar,$en,$type]){if($i){ ?><div class="receipt-cut-line"><span><i class="fa-solid fa-scissors" aria-hidden="true"></i> <?= $this->t('قص هنا (خط فصل الإيصالات)','Cut here · receipt separation') ?></span></div><?php } ?>
        <article class="receipt-slip"><div class="receipt-watermark" aria-hidden="true"><?= $this->t('إيصال استلام نقدية','Cash receipt voucher') ?></div><header class="receipt-slip-header"><div class="receipt-slip-brand"><div class="receipt-slip-logo"><?= $this->receiptLogo($brand) ?></div><div><h2><?= self::e($brand['name']) ?></h2><p><?= self::e($brand['phone']!==''?$this->t('هاتف: ','Phone: ').$brand['phone']:$this->t($this->s['office']==='china'?'فرع الصين':'فرع مصر',ucfirst($this->s['office']).' office')) ?></p></div></div><div class="receipt-slip-title"><strong><?= $this->t('إيصال استلام نقدية','Cash receipt voucher') ?></strong><small>CASH RECEIPT VOUCHER</small></div><div class="receipt-slip-reference"><span class="receipt-copy receipt-copy-<?= $type ?>"><?= $this->t($ar,$en) ?></span><p><?= $this->t('رقم:','No:') ?> <bdi><?= self::e($this->receiptReference($row)) ?></bdi></p><p><?= $this->t('التاريخ:','Date:') ?> <bdi><?= self::e($v['date']) ?></bdi></p></div></header>
        <div class="receipt-slip-content"><div class="receipt-amount-banner"><div><?= $this->t('المبلغ:','Amount:') ?> <strong><?= $this->money($v['amount'],$v['currency']) ?></strong></div><div><?= $this->t('طريقة الدفع:','Payment method:') ?> <b><?= self::e($this->receiptMethod($v['method'])) ?></b></div></div><div class="receipt-writing-line"><b><?= $this->t('استلمنا من السيد / السادة:','Received from:') ?></b><span><?= self::e($v['payer']) ?><?php if($v['phone']!==''){ ?><small> (<?= $this->t('هاتف:','Phone:') ?> <bdi><?= self::e($v['phone']) ?></bdi>)</small><?php } ?></span></div><div class="receipt-writing-line receipt-words"><b><?= $this->t('مبلغ وقدره (كتابةً):','Amount in words:') ?></b><span><?= self::e(self::receiptWords($v['amount'],$v['currency'],$this->ar)) ?></span></div><div class="receipt-writing-line"><b><?= $this->t('وذلك عن (البيان):','For / purpose:') ?></b><span><?= self::e($v['purpose']) ?></span></div><?php if($v['notes']!==''){ ?><div class="receipt-writing-line receipt-notes"><b><?= $this->t('ملاحظات:','Notes:') ?></b><span><?= nl2br(self::e($v['notes'])) ?></span></div><?php } ?></div>
        <footer class="receipt-slip-footer"><div><b><?= $this->t('المستلم المسؤول','Responsible recipient') ?></b><strong><?= self::e($receiver) ?></strong><small><?= $this->t('التوقيع:','Signature:') ?> ....................</small></div><div><b><?= $this->t('توقيع الدافع (العميل)','Payer / customer signature') ?></b><span class="receipt-signature-space"></span><small><?= $this->t('التوقيع:','Signature:') ?> ....................</small></div><div><b><?= $this->t('اعتماد الحسابات / الخاتم','Accounts approval / stamp') ?></b><span class="receipt-signature-space"></span><small><?= $this->t('الاعتماد:','Approval:') ?> ....................</small></div><div class="receipt-qr"><?php if($qr!==''){ ?><div class="receipt-qr-box"><?= $qr ?></div><small><?= $this->t('عرض الإيصال · دخول مطلوب','View receipt · sign-in required') ?></small><?php }else{ ?><i class="fa-solid fa-lock" aria-hidden="true"></i><small><?= $this->t('إيصال داخلي','Internal receipt') ?></small><?php } ?></div></footer><p class="receipt-slip-status"><?= self::e($row['status']==='archived'?$this->t('مؤرشف · غير مرحل ماليًا','Archived · not posted'):$this->status($row['status'])) ?></p></article><?php } ?></div></div><?php
    }

    private function printDocument(array $row): void
    {
        $v=$row['content'];$this->letterhead($this->s['settings']??['name'=>'China Planet','phone'=>''],$this->label($row['kind'])); ?><article class="workspace-card workspace-print-document"><h2><?= self::e($this->label($row['kind'])) ?></h2><p class="workspace-print-draft"><?= self::e($this->status($row['status'])) ?></p><dl><dt><?= $this->t('المرجع','Reference') ?></dt><dd><bdi><?= self::e($row['id']) ?></bdi></dd><?php foreach($v as$k=>$value){if($k==='_finance')continue;if(in_array($k,['category_ref','settles_ref','source_ref'],true)&&$value==='')continue; ?><dt><?= self::e($this->fieldLabel($k)) ?></dt><dd><?= self::e($k==='user_id'?$this->name((int)$value):$value) ?></dd><?php } ?></dl><p><?= $this->t('إعداد الطلب / التوقيع: ____________________','Prepared by / signature: ____________________') ?></p><button class="button button-brand" type="button" data-workspace-print><?= $this->t('طباعة / حفظ PDF','Print / save PDF') ?></button></article><?php
    }
    private function details(array $row): void
    { ?><section class="workspace-card"><h2><?= self::e($this->label($row['kind'])) ?></h2><dl><?php foreach($row['content']as$key=>$value){if($key==='_finance')continue; ?><dt><?= self::e($this->fieldLabel($key)) ?></dt><dd><?= self::e(is_bool($value)?$this->t($value?'نشط':'متوقف',$value?'Active':'Inactive'):$value) ?></dd><?php } ?></dl></section><?php }
    private function fieldLabel(string $k): string
    {
        $labels=['user_id'=>['الموظف','Employee'],'date'=>['التاريخ','Date'],'month'=>['الشهر','Month'],'base'=>['الأساسي','Base'],'bonus'=>['مكافأة','Bonus'],'deduction'=>['الخصومات','Deductions'],'loan_repayment'=>['سداد سلفة','Loan repayment'],'gross'=>['الإجمالي','Gross'],'net'=>['الصافي','Net'],'amount'=>['المبلغ','Amount'],'currency'=>['العملة','Currency'],'payer'=>['استلمنا من','Received from'],'phone'=>['الهاتف','Phone'],'method'=>['الطريقة','Method'],'purpose'=>['الغرض','Purpose'],'notes'=>['ملاحظات','Notes'],'source'=>['المصدر','Source'],'source_ref'=>['مرجع المستند','Source reference'],'category_ref'=>['مرجع البند','Category reference'],'settles_ref'=>['مرجع العهدة','Advance reference']];return $labels[$k][$this->ar?0:1]??$k;
    }
